const __pageData = JSON.parse('{"title":"Week 7 solutions — spoilers","description":"","frontmatter":{"search":false,"prev":false,"next":false},"headers":[],"relativePath":"solutions/week-07.md","filePath":"solutions/week-07.md"}');
